<main class="brands-page"><section class="brands-hero"><?php if($page['hero_image_id']):?><div class="brands-hero-image" style="background-image:url('<?=e(media_url($page['hero_image_id']))?>')"></div><?php endif?><div class="container"><span class="brands-kicker"><?=text('trusted_brands')?></span><h1><?=e($page['hero_heading']?:$page['title'])?></h1><p><?=e($page['subtitle'])?></p></div></section><section class="brands-wrap"><div class="brands-panel"><div><h2><?=text('all_brands')?></h2><p><?=text('brand_intro')?></p></div><a href="<?=e(cms_url('/products/'))?>"><i class="fa-solid fa-boxes-stacked"></i> <?=text('view_products')?></a></div><div class="brands-grid"><?php foreach($brands as $brand):?><a class="brand-tile reveal" href="<?=e(cms_url('/products/?brand='.$brand['id']))?>"><span class="brand-logo-box"><?php if($brand['image_id']):?><?=media_img($brand['image_id'],$brand['title'])?><?php else:?><span class="brand-initial"><?=e(mb_substr($brand['title'],0,1))?></span><?php endif?></span><strong><?=e($brand['title'])?></strong><small><?=e($brand['description']?:setting('text.view_brand_products'))?></small><span class="brand-action"><?=text('view_products')?> <i class="fa-solid fa-arrow-right"></i></span></a><?php endforeach?><?php if(!$brands):?><div class="brands-empty"><i class="fa-solid fa-box-open"></i><h3><?=text('no_data')?></h3><p><?=text('no_brands')?></p></div><?php endif?></div></section><?php if($page['body']):?><section class="section-padding"><div class="container rich-text"><?=rich($page['body'])?></div></section><?php endif?><?php foreach($sections as $section)cms_view('public/section',compact('section'));?></main>
